<template>
  <div class="page-system-settings">
    <div class="page-header">
      <h2>{{ t('settings.system.title') }}</h2>
    </div>

    <el-card v-loading="loading">
      <el-alert
        v-if="!loading"
        :title="t('settings.system.readonlyHint')"
        type="info"
        :closable="false"
        style="margin-bottom: 16px"
      />

      <el-descriptions :column="1" border>
        <el-descriptions-item label="PUBLIC_SERVER_URL">
          {{ settings.public_server_url || '-' }}
        </el-descriptions-item>
        <el-descriptions-item :label="t('settings.system.alertDetector')">
          {{ settings.alert_detector_enabled ? t('common.enabled') : t('common.disabled') }}
        </el-descriptions-item>
        <el-descriptions-item :label="t('settings.system.localAgent')">
          {{ settings.local_agent_enabled ? t('common.enabled') : t('common.disabled') }}
        </el-descriptions-item>
        <el-descriptions-item :label="t('settings.system.metricBackendCheck')">
          {{ settings.metric_backend_health_check_at_startup ? t('common.yes') : t('common.no') }}
        </el-descriptions-item>
        <el-descriptions-item :label="t('settings.system.logDir')">
          {{ settings.log_dir }}
        </el-descriptions-item>
        <el-descriptions-item :label="t('settings.system.backupDir')">
          {{ settings.backup_dir }}
        </el-descriptions-item>
        <el-descriptions-item label="InfluxDB URL">
          {{ settings.influxdb_url }}
        </el-descriptions-item>
        <el-descriptions-item label="InfluxDB Org">
          {{ settings.influxdb_org }}
        </el-descriptions-item>
        <el-descriptions-item label="InfluxDB Bucket">
          {{ settings.influxdb_bucket }}
        </el-descriptions-item>
        <el-descriptions-item :label="t('settings.system.influxRetentionDays')">
          {{ settings.influxdb_retention_days }}
        </el-descriptions-item>
        <el-descriptions-item :label="t('settings.system.sessionMaxAgeDays')">
          {{ settings.user_session_max_age_days }}
        </el-descriptions-item>
        <el-descriptions-item :label="t('settings.system.sessionSlideDays')">
          {{ settings.user_session_slide_days }}
        </el-descriptions-item>
      </el-descriptions>
    </el-card>
  </div>
</template>

<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { getSystemSettings, type SystemSettingsRead } from '@/api/settings'
import { showError } from '@/utils/error'

const { t } = useI18n()
const settings = ref<Partial<SystemSettingsRead>>({})
const loading = ref(false)

async function loadSettings() {
  loading.value = true
  try {
    settings.value = await getSystemSettings()
  } catch (error) {
    showError(error, t('settings.system.loadFailed'))
  } finally {
    loading.value = false
  }
}

onMounted(() => {
  loadSettings()
})
</script>

<style scoped>
.page-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
}

.page-header h2 {
  margin: 0;
}
</style>
